class TripLedger {
  #records = [];
  #ids = new Set();

  constructor(records = []) {
    if (!Array.isArray(records)) throw new TypeError('records must be an array');
    for (const record of records) this.add(record);
  }

  add(record) {
    const normalized = TripLedger.#normalize(record);
    if (this.#ids.has(normalized.id)) throw new RangeError('duplicate id');
    this.#records.push(normalized);
    this.#ids.add(normalized.id);
    return TripLedger.#copy(normalized);
  }

  list() {
    return this.#records.map(record => TripLedger.#copy(record));
  }

  select(id) {
    TripLedger.#checkId(id);
    const found = this.#records.find(record => record.id === id);
    return found ? TripLedger.#copy(found) : null;
  }

  remove(id) {
    TripLedger.#checkId(id);
    const index = this.#records.findIndex(record => record.id === id);
    if (index < 0) return false;
    this.#records.splice(index, 1);
    this.#ids.delete(id);
    return true;
  }

  toJSON() {
    return JSON.stringify(this.#records);
  }

  static fromJSON(text) {
    if (typeof text !== 'string') throw new TypeError('text must be a string');
    let value;
    try {
      value = JSON.parse(text);
    } catch (_) {
      throw new TypeError('invalid JSON');
    }
    if (!Array.isArray(value)) throw new TypeError('JSON root must be an array');
    return new TripLedger(value);
  }

  static #checkId(id) {
    if (typeof id !== 'string' || id.length === 0) throw new TypeError('invalid id');
  }

  static #finite(value, name, allowZero = false) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(name + ' must be finite');
    }
    if (allowZero ? value < 0 : value <= 0) {
      throw new RangeError(name + ' is out of range');
    }
    return value;
  }

  static #normalize(record) {
    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new TypeError('invalid record');
    }
    TripLedger.#checkId(record.id);
    if (record.mode !== 'walk' && record.mode !== 'paddle') {
      throw new TypeError('invalid mode');
    }
    if (!Array.isArray(record.points)) throw new TypeError('points must be an array');
    if (record.points.length === 0) throw new RangeError('points must be non-empty');

    const points = record.points.map(point => {
      if (!point || typeof point !== 'object' || Array.isArray(point)) {
        throw new TypeError('invalid point');
      }
      if (typeof point.lat !== 'number' || !Number.isFinite(point.lat) ||
          typeof point.lon !== 'number' || !Number.isFinite(point.lon)) {
        throw new TypeError('coordinates must be finite');
      }
      if (point.lat < -90 || point.lat > 90 || point.lon < -180 || point.lon > 180) {
        throw new RangeError('coordinate out of range');
      }
      return { lat: point.lat, lon: point.lon };
    });

    const result = {
      id: record.id,
      mode: record.mode,
      distanceKm: TripLedger.#finite(record.distanceKm, 'distanceKm'),
      durationMinutes: TripLedger.#finite(record.durationMinutes, 'durationMinutes'),
      points
    };

    if (record.mode === 'walk') {
      if ('currentKnots' in record) throw new TypeError('walk cannot have currentKnots');
      result.stepRate = TripLedger.#finite(record.stepRate, 'stepRate');
    } else {
      if ('stepRate' in record) throw new TypeError('paddle cannot have stepRate');
      result.currentKnots = TripLedger.#finite(record.currentKnots, 'currentKnots', true);
    }
    return result;
  }

  static #copy(record) {
    return { ...record, points: record.points };
  }
}

module.exports = { TripLedger };

