'use strict';
const assert = require('node:assert');
const { TripLedger } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['TripLedger']);

const source = {
  id: 'w1', mode: 'walk', distanceKm: 2.5, durationMinutes: 30,
  points: [{ lat: 12.5, lon: 77.6 }], stepRate: 110,
  ignored: 'remove me'
};
const ledger = new TripLedger([source]);
source.id = 'changed';
source.points[0].lat = 0;

assert.deepStrictEqual(ledger.select('w1'), {
  id: 'w1', mode: 'walk', distanceKm: 2.5, durationMinutes: 30,
  points: [{ lat: 12.5, lon: 77.6 }], stepRate: 110
});
assert.strictEqual(ledger.select('missing'), null);

const paddleInput = {
  id: 'p1', mode: 'paddle', distanceKm: 4, durationMinutes: 45,
  points: [{ lat: -90, lon: -180 }, { lat: 90, lon: 180 }],
  currentKnots: 0, unknown: { nested: true }
};
const added = ledger.add(paddleInput);
assert.deepStrictEqual(added, {
  id: 'p1', mode: 'paddle', distanceKm: 4, durationMinutes: 45,
  points: [{ lat: -90, lon: -180 }, { lat: 90, lon: 180 }], currentKnots: 0
});
added.points[0].lat = 3;
paddleInput.points[1].lon = 0;
assert.strictEqual(ledger.select('p1').points[0].lat, -90);
assert.strictEqual(ledger.select('p1').points[1].lon, 180);

const listed = ledger.list();
assert.deepStrictEqual(listed.map(x => x.id), ['w1', 'p1']);
listed[0].id = 'mutated';
listed[0].points.push({ lat: 0, lon: 0 });
assert.deepStrictEqual(ledger.list().map(x => x.id), ['w1', 'p1']);
assert.strictEqual(ledger.select('w1').points.length, 1);

assert.throws(() => ledger.add({ ...ledger.select('w1') }), RangeError);
assert.deepStrictEqual(ledger.list().map(x => x.id), ['w1', 'p1']);
assert.strictEqual(ledger.remove('w1'), true);
assert.strictEqual(ledger.remove('w1'), false);
assert.deepStrictEqual(ledger.list().map(x => x.id), ['p1']);
assert.throws(() => ledger.select(''), TypeError);
assert.throws(() => ledger.remove(1), TypeError);

const json1 = ledger.toJSON();
const json2 = ledger.toJSON();
assert.strictEqual(json1, json2);
assert.deepStrictEqual(JSON.parse(json1), ledger.list());
const restored = TripLedger.fromJSON(json1);
assert.deepStrictEqual(restored.list(), ledger.list());
const restoredList = restored.list();
restoredList[0].points[0].lon = 42;
assert.strictEqual(restored.select('p1').points[0].lon, -180);
assert.throws(() => TripLedger.fromJSON('{'), TypeError);
assert.throws(() => TripLedger.fromJSON('{}'), TypeError);
assert.throws(() => TripLedger.fromJSON(1), TypeError);
assert.deepStrictEqual(new TripLedger().list(), []);
assert.deepStrictEqual(TripLedger.fromJSON('[]').list(), []);

const base = { id: 'x', mode: 'walk', distanceKm: 1, durationMinutes: 1, points: [{ lat: 0, lon: 0 }], stepRate: 1 };
assert.throws(() => ledger.add({ ...base, id: '' }), TypeError);
assert.throws(() => ledger.add({ ...base, id: 'x2', distanceKm: 0 }), RangeError);
assert.throws(() => ledger.add({ ...base, id: 'x3', durationMinutes: Infinity }), TypeError);
assert.throws(() => ledger.add({ ...base, id: 'x4', points: [] }), RangeError);
assert.throws(() => ledger.add({ ...base, id: 'x5', points: [{ lat: 91, lon: 0 }] }), RangeError);
assert.throws(() => ledger.add({ ...base, id: 'x6', currentKnots: 0 }), TypeError);
assert.throws(() => ledger.add({ ...base, id: 'x7', mode: 'paddle', currentKnots: 1 }), TypeError);

